const QUESTIONS = [{"id": "a1", "section": "A", "title": "Soalan 1", "intro": "Situasi manakah menunjukkan daya tarikan?", "fields": [{"id": "a1", "type": "choice", "label": "Pilih satu jawapan.", "options": ["Menendang bola ke arah gol", "Menolak troli ke hadapan", "Menarik laci meja untuk membukanya", "Menekan plastisin dengan tapak tangan"], "answer": 2, "max": 1, "model": "Menarik laci meja untuk membukanya"}]}, {"id": "a2", "section": "A", "title": "Soalan 2", "intro": "Apakah cara paling sesuai menguruskan surat khabar lama?", "fields": [{"id": "a2", "type": "choice", "label": "Pilih satu jawapan.", "options": ["Membakarnya di halaman rumah", "Menghantarnya ke pusat kitar semula", "Membuangnya ke dalam sungai", "Menanamnya bersama sisa makanan"], "answer": 1, "max": 1, "model": "Menghantarnya ke pusat kitar semula"}]}, {"id": "a3", "section": "A", "title": "Soalan 3", "intro": "Organ manakah membentuk sistem saraf pusat manusia?", "fields": [{"id": "a3", "type": "choice", "label": "Pilih satu jawapan.", "options": ["Otak dan saraf tunjang", "Otak dan jantung", "Saraf tunjang dan paru-paru", "Jantung dan salur darah"], "answer": 0, "max": 1, "model": "Otak dan saraf tunjang"}]}, {"id": "a4", "section": "A", "title": "Soalan 4", "intro": "Sengkenit menghisap darah kerbau. Apakah hubungan antara kedua-dua haiwan ini?", "fields": [{"id": "a4", "type": "choice", "label": "Pilih satu jawapan.", "options": ["Mutualisme", "Komensalisme", "Persaingan", "Parasitisme"], "answer": 3, "max": 1, "model": "Parasitisme"}]}, {"id": "a5", "section": "A", "title": "Soalan 5", "intro": "Dua pelari berlari sejauh 100 m. Ali mengambil masa 15 saat manakala Ravi mengambil masa 20 saat. Mengapakah Ali lebih laju?", "fields": [{"id": "a5", "type": "choice", "label": "Pilih satu jawapan.", "options": ["Ali berlari pada jarak yang lebih jauh", "Ali mengambil masa yang lebih singkat bagi jarak yang sama", "Ali mengambil masa yang lebih lama", "Ravi berlari pada jarak yang lebih pendek"], "answer": 1, "max": 1, "model": "Ali mengambil masa yang lebih singkat bagi jarak yang sama"}]}, {"id": "a6", "section": "A", "title": "Soalan 6", "intro": "Semasa gerhana Bulan separa, apakah yang berlaku?", "fields": [{"id": "a6", "type": "choice", "label": "Pilih satu jawapan.", "options": ["Seluruh Bulan memasuki kawasan umbra Bumi", "Bulan berada di antara Matahari dengan Bumi", "Sebahagian Bulan memasuki kawasan umbra Bumi", "Bumi berada di luar garisan antara Matahari dengan Bulan"], "answer": 2, "max": 1, "model": "Sebahagian Bulan memasuki kawasan umbra Bumi"}]}, {"id": "a7", "section": "A", "title": "Soalan 7", "intro": "Apakah kesan buruk mikroorganisma?", "fields": [{"id": "a7", "type": "choice", "label": "Pilih satu jawapan.", "options": ["Membantu menghasilkan yogurt", "Membantu doh roti mengembang", "Menguraikan sisa organik", "Menyebabkan makanan menjadi rosak"], "answer": 3, "max": 1, "model": "Menyebabkan makanan menjadi rosak"}]}, {"id": "a8", "section": "A", "title": "Soalan 8", "intro": "Apakah kebaikan penggunaan mesin menuai padi kepada petani?", "fields": [{"id": "a8", "type": "choice", "label": "Pilih satu jawapan.", "options": ["Memendekkan masa menuai padi", "Menghapuskan keperluan air bagi pokok padi", "Menghalang semua penyakit tanaman", "Menjadikan tanah subur secara automatik"], "answer": 0, "max": 1, "model": "Memendekkan masa menuai padi"}]}, {"id": "a9", "section": "A", "title": "Soalan 9", "intro": "Mengapakah ikan dikeringkan untuk mengawetnya?", "fields": [{"id": "a9", "type": "choice", "label": "Pilih satu jawapan.", "options": ["Untuk menambah kandungan air dalam ikan", "Untuk menambah bilangan mikroorganisma", "Untuk mengurangkan air yang diperlukan bagi pertumbuhan mikroorganisma", "Untuk memastikan semua mikroorganisma membiak dengan cepat"], "answer": 2, "max": 1, "model": "Untuk mengurangkan air yang diperlukan bagi pertumbuhan mikroorganisma"}]}, {"id": "a10", "section": "A", "title": "Soalan 10", "intro": "Pernyataan manakah benar tentang Galaksi Bima Sakti?", "fields": [{"id": "a10", "type": "choice", "label": "Pilih satu jawapan.", "options": ["Berbentuk elips dan tidak mengandungi bintang", "Berbentuk pilin dan mengandungi Sistem Suria", "Berbentuk tidak sekata dan hanya mengandungi Bumi", "Berbentuk sfera dan hanya mengandungi Matahari"], "answer": 1, "max": 1, "model": "Berbentuk pilin dan mengandungi Sistem Suria"}]}, {"id": "b1", "section": "B", "title": "1. Sistem saraf manusia", "intro": "Jawab semua bahagian berikut.", "fields": [{"id": "b1ai", "type": "choice", "label": "(a)(i) Organ yang mentafsir maklumat dan mengawal tindakan badan.", "options": ["Otak", "Saraf tunjang", "Jantung"], "answer": 0, "max": 1, "model": "Otak"}, {"id": "b1aii", "type": "choice", "label": "(a)(ii) Menghubungkan otak dengan saraf periferi serta mengawal tindakan refleks tertentu.", "options": ["Otak", "Saraf tunjang", "Jantung"], "answer": 1, "max": 1, "model": "Saraf tunjang"}, {"id": "b1bi", "type": "choice", "label": "(b)(i) Memakai topi keledar dapat melindungi otak.", "options": ["BETUL", "SALAH"], "answer": 0, "max": 1, "model": "BETUL"}, {"id": "b1bii", "type": "choice", "label": "(b)(ii) Pengambilan dadah baik untuk sistem saraf.", "options": ["BETUL", "SALAH"], "answer": 1, "max": 1, "model": "SALAH"}]}, {"id": "b2", "section": "B", "title": "2. Pengurusan bahan buangan & pengawetan", "intro": "Pilih jawapan yang paling sesuai.", "fields": [{"id": "b2ai", "type": "choice", "label": "(a)(i) Menggunakan balang jem kosong sebagai bekas pensel.", "options": ["Mengurangkan", "Mengguna semula", "Mengitar semula"], "answer": 1, "max": 1, "model": "Mengguna semula"}, {"id": "b2aii", "type": "choice", "label": "(a)(ii) Membawa beg sendiri supaya penggunaan beg plastik berkurang.", "options": ["Mengurangkan", "Mengguna semula", "Mengitar semula"], "answer": 0, "max": 1, "model": "Mengurangkan"}, {"id": "b2bi", "type": "choice", "label": "(b)(i) Ikan disimpan pada suhu -18°C menggunakan kaedah...", "options": ["Penyejukbekuan", "Penjerukan"], "answer": 0, "max": 1, "model": "Penyejukbekuan"}, {"id": "b2bii", "type": "choice", "label": "(b)(ii) Pengeringan mengurangkan kandungan _____ dalam makanan.", "options": ["Air", "Oksigen"], "answer": 0, "max": 1, "model": "Air"}]}, {"id": "c1", "section": "C", "title": "1. Tekanan udara di kawasan gunung", "intro": "Seorang murid mengkaji tekanan udara pada ketinggian berbeza di sebuah gunung. Bacaan diambil menggunakan alat pengukur tekanan udara yang sama. Data simulasi berikut diperoleh.", "table": [["Ketinggian dari aras laut (m)", "Tekanan udara (kPa)"], ["0", "100"], ["1 000", "90"], ["2 000", "80"], ["3 000", "70"]], "fields": [{"id": "c1a", "type": "text", "label": "(a) Tulis hipotesis dalam bentuk “Jika ..., maka ...”.", "model": "Jika ketinggian dari aras laut bertambah, maka tekanan udara berkurang.", "rules": [[["jika"], ["tinggi", "ketinggian"], ["bertambah", "meningkat", "naik"]], [["maka"], ["tekanan"], ["berkurang", "menurun", "rendah"]]], "max": 2}, {"id": "c1b", "type": "table", "label": "(b) Bina semula jadual bagi ketinggian 0 m dan 2 000 m. Tulis kedua-dua tajuk lajur berserta unit.", "max": 2, "model": "Ketinggian dari aras laut (m) | Tekanan udara (kPa)\n0 | 100\n2 000 | 80"}, {"id": "c1c", "type": "text", "label": "(c) Nyatakan pola perubahan tekanan udara apabila ketinggian bertambah.", "model": "Tekanan udara menurun / berkurang.", "rules": [[["tekanan"], ["menurun", "berkurang", "rendah"]]], "max": 1}, {"id": "c1d", "type": "text", "label": "(d) Tulis kesimpulan dalam bentuk “Semakin ..., semakin ...”.", "model": "Semakin bertambah ketinggian dari aras laut, semakin berkurang tekanan udara.", "rules": [[["semakin"], ["tinggi", "ketinggian"], ["bertambah", "meningkat", "naik"], ["tekanan"], ["berkurang", "menurun", "rendah"]]], "max": 1}, {"id": "c1e", "type": "text", "label": "(e) Mengapakah tekanan udara lebih rendah di puncak gunung berbanding di kaki gunung?", "model": "Udara kurang padat / lebih sedikit zarah bagi isi padu sama (1). Kekerapan perlanggaran zarah pada permukaan lebih rendah, maka tekanan lebih rendah (1). Alternatif: lapisan udara di atas lebih sedikit (1), berat udara yang menekan lebih kecil (1).", "rules": [[["kurang padat", "sedikit zarah", "zarah kurang", "lapisan udara", "lebih sedikit udara"]], [["perlanggaran", "pelanggaran", "berat udara"], ["kurang", "rendah", "kecil", "sedikit"]]], "max": 2}]}, {"id": "c2", "section": "C", "title": "2. Pengawetan ikan", "intro": "Dua ekor ikan daripada jenis dan jisim yang sama disediakan. Ikan P dibiarkan segar, manakala ikan Q dikeringkan. Kedua-duanya disimpan dalam bekas berasingan yang serupa pada suhu bilik. Bau dan keadaan isi diperhatikan setiap hari.", "table": [["Ikan", "Rawatan", "Pemerhatian pada hari ketiga"], ["P", "Tidak dikeringkan", "Berbau busuk dan isinya lembik"], ["Q", "Dikeringkan", "Tidak berbau busuk dan isinya keras"]], "fields": [{"id": "c2a", "type": "text", "label": "(a) Nyatakan satu pemerhatian tentang ikan P pada hari ketiga.", "model": "Ikan P berbau busuk / isinya lembik.", "rules": [[["busuk", "lembik"]]], "max": 1}, {"id": "c2b", "type": "text", "label": "(b) Berikan satu inferens mengapa ikan P berbau busuk.", "model": "Mikroorganisma membiak / aktif pada ikan P lalu menyebabkan ikan rosak.", "rules": [[["mikroorganisma", "bakteria", "kuman"], ["membiak", "aktif", "bertumbuh", "pertumbuhan"]]], "max": 1}, {"id": "c2ci", "type": "text", "label": "(c)(i) Nyatakan pemboleh ubah dimanipulasikan.", "model": "Rawatan ikan: dikeringkan atau tidak dikeringkan.", "rules": [[["rawatan", "pengeringan", "dikeringkan", "keadaan awal", "segar"]]], "max": 1}, {"id": "c2cii", "type": "text", "label": "(c)(ii) Nyatakan pemboleh ubah bergerak balas.", "model": "Keadaan / kerosakan ikan pada hari ketiga berdasarkan bau atau keadaan isi.", "rules": [[["bau", "kerosakan ikan", "keadaan ikan", "keadaan isi", "tekstur"]]], "max": 1}, {"id": "c2d", "type": "text", "label": "(d) Nyatakan satu pemboleh ubah dimalarkan.", "model": "Jenis ikan / jisim awal ikan / suhu penyimpanan / tempoh pemerhatian / jenis atau saiz bekas.", "rules": [[["jenis ikan", "jisim", "suhu", "tempoh", "saiz bekas", "jenis bekas"]]], "max": 1}, {"id": "c2e", "type": "text", "label": "(e) Berikan definisi secara operasi bagi ikan yang rosak dalam penyiasatan ini.", "model": "Ikan yang rosak ialah ikan yang berbau busuk (1) dan mempunyai isi lembik (1) pada hari ketiga.", "rules": [[["busuk"]], [["lembik"]]], "max": 2}, {"id": "c2f", "type": "text", "label": "(f) Bagaimanakah pengeringan melambatkan kerosakan ikan?", "model": "Mengurangkan kandungan air lalu merencat pertumbuhan mikroorganisma.", "rules": [[["air"], ["kurang"], ["mikroorganisma", "bakteria", "kuman"], ["merencat", "melambat", "menghalang", "sukar", "tidak dapat", "kurang"]]], "max": 1}]}, {"id": "c3", "section": "C", "title": "3. Haiwan diancam kepupusan", "intro": "Jadual menunjukkan bilangan penyu yang mendarat untuk bertelur di Pantai X. Telur penyu diambil untuk dijual. Lampu bangunan berhampiran pantai dipasang sepanjang malam. Data simulasi untuk latihan.", "table": [["Tahun", "Bilangan penyu yang mendarat (ekor)"], ["2022", "80"], ["2023", "60"], ["2024", "40"], ["2025", "20"]], "fields": [{"id": "c3a", "type": "text", "label": "(a) Nyatakan pola perubahan bilangan penyu dan satu bukti daripada jadual.", "model": "Bilangan penyu semakin berkurang (1); daripada 80 ekor pada 2022 kepada 20 ekor pada 2025 / berkurang 20 ekor setiap tahun (1).", "rules": [[["kurang", "menurun", "merosot"]], [["80"], ["20"]]], "max": 2}, {"id": "c3b", "type": "text", "label": "(b) Terangkan bagaimana pengambilan telur secara berterusan boleh menyebabkan kepupusan penyu.", "model": "Telur yang diambil tidak dapat menetas (1). Bilangan penyu baharu / populasi berkurang dan boleh pupus (1).", "rules": [[["telur"], ["tidak", "kurang", "gagal"], ["menetas"]], [["penyu", "populasi"], ["kurang", "pupus", "merosot"]]], "max": 2}, {"id": "c3c", "type": "text", "label": "(c) Cadangkan dua langkah untuk melindungi penyu di Pantai X.", "model": "Dua langkah berbeza: larang pengambilan / penjualan telur; pusat penetasan; kawasan perlindungan; kawal pencahayaan; kempen kesedaran.", "rules": [[["larang", "kuatkuasa", "penetasan", "perlindungan", "wartakan", "cahaya", "lampu", "kempen"]], [["larang", "kuatkuasa", "penetasan", "perlindungan", "wartakan", "cahaya", "lampu", "kempen"]]], "max": 2}, {"id": "c3d", "type": "text", "label": "(d) Wajarkah hotel baharu dibina di kawasan penyu bertelur? Berikan keputusan dan satu alasan.", "model": "Tidak wajar (1), kerana mengganggu / memusnahkan habitat, kawasan bertelur, atau menyebabkan gangguan cahaya dan manusia (1). Terima keputusan lain dengan alasan perlindungan yang konsisten dan munasabah.", "rules": [[["tidak wajar", "tidak setuju", "tidak patut"]], [["habitat", "kawasan bertelur", "cahaya", "ganggu", "musnah"]]], "max": 2}]}, {"id": "c4", "section": "C", "title": "4. Kekuatan dan kestabilan struktur", "intro": "Dua jambatan model dibina menggunakan kertas daripada jenis dan saiz yang sama. Jarak antara penyokong adalah sama. Syiling yang sama jisim ditambah satu demi satu sehingga jambatan mula melendut.", "table": [["Jambatan", "Bentuk kertas", "Syiling sebelum mula melendut"], ["P", "Kepingan rata", "3"], ["Q", "Lipatan beralun", "12"]], "fields": [{"id": "c4a", "type": "text", "label": "(a) Jambatan manakah lebih kuat?", "model": "Jambatan Q.", "rules": [[["q"]]], "max": 1}, {"id": "c4b", "type": "text", "label": "(b) Berikan satu inferens mengapa jambatan itu menampung lebih banyak syiling.", "model": "Bentuk lipatan beralun menjadikan kertas lebih kuat / tahan lenturan.", "rules": [[["lipatan", "beralun", "dilipat"], ["kuat", "tahan", "kukuh"]]], "max": 1}, {"id": "c4c", "type": "text", "label": "(c) Nyatakan pemboleh ubah dimanipulasikan.", "model": "Bentuk kertas / bentuk struktur jambatan.", "rules": [[["bentuk kertas", "bentuk struktur", "bentuk jambatan", "lipatan"]]], "max": 1}, {"id": "c4d", "type": "text", "label": "(d) Ramalkan keadaan jambatan P apabila syiling kelima diletakkan.", "model": "Jambatan P melendut / melendut lebih banyak / runtuh.", "rules": [[["melendut", "runtuh"]]], "max": 1}, {"id": "c4e", "type": "text", "label": "(e) Cadangkan cara lain menambahkan kekuatan jambatan P tanpa menukar jenis kertas. Jelaskan sebabnya.", "model": "Tambah lapisan kertas (1) supaya lebih tebal dan menampung beban lebih besar (1). Alternatif: penyokong di tengah (1) supaya rentang tanpa sokongan lebih pendek (1).", "rules": [[["lapisan", "tindih", "penyokong", "sokongan"]], [["tebal", "beban", "pendek", "melendut"]]], "max": 2}, {"id": "c4f", "type": "text", "label": "(f) Menara R dan S sama tinggi dengan taburan jisim sama. Tapak R selebar 4 cm dan tapak S selebar 10 cm. Menara manakah lebih stabil? Jelaskan.", "model": "Menara S (1), kerana tapaknya lebih lebar / luas dan lebih sukar tumbang (1).", "rules": [[["s"]], [["tapak"], ["lebar", "luas"]]], "max": 2}]}];
